--------------------------------------------------------------------------------
-- 04_xxfnd_triggers.sql
-- Row rules on common tables that are not covered by constraints.
-- (WHO and audit triggers are generated by XXFND_UTIL_PKG / XXFND_AUDIT_PKG.)
--------------------------------------------------------------------------------

-- Lookup customization level (EBS): S = values locked, E = values may be added
-- but not changed or deleted, U = fully editable. Applies to changes made in
-- the application; install scripts (no APEX session) are not restricted.
create or replace trigger xxfnd_lookup_values_lvl
    before insert or update or delete on xxfnd_lookup_values
    for each row
declare
    l_level xxfnd_lookup_types.customization_level%type;
begin
    if not xxfnd_util_pkg.in_apex_session then
        return;
    end if;
    select customization_level into l_level
      from xxfnd_lookup_types
     where lookup_type = coalesce(:new.lookup_type, :old.lookup_type);
    if l_level = 'S' then
        raise_application_error(-20130, 'Values of this lookup type are defined by the system and cannot be changed.');
    elsif l_level = 'E' and (deleting or (updating and (:new.lookup_code <> :old.lookup_code))) then
        raise_application_error(-20131, 'Values of this lookup type can be added or disabled, but not deleted or recoded.');
    end if;
end;
/

-- Fusion-sourced people are owned by the HCM sync; only the sync (no APEX
-- session) may change their identity fields.
create or replace trigger xxfnd_employees_src
    before update or delete on xxfnd_employees
    for each row
begin
    if xxfnd_util_pkg.in_apex_session and not xxfnd_security_pkg.sync_running
       and :old.source_type = 'FUSION' then
        if deleting
           or :new.user_name     <> :old.user_name
           or :new.full_name     <> :old.full_name
           or :new.email_address <> :old.email_address
           or :new.source_type   <> :old.source_type
           or nvl(:new.fusion_person_id, -1) <> nvl(:old.fusion_person_id, -1) then
            raise_application_error(-20132, 'This person comes from Oracle Fusion HCM; change them there.');
        end if;
    end if;
    if updating then
        :new.user_name := upper(:new.user_name);
    end if;
end;
/

create or replace trigger xxfnd_employees_ins
    before insert on xxfnd_employees
    for each row
begin
    :new.user_name := upper(:new.user_name);
    :new.email_address := lower(:new.email_address);
end;
/

-- SoD pairs are stored in canonical order whatever order the user picks.
create or replace trigger xxfnd_sod_rules_order
    before insert or update of role_code_1, role_code_2 on xxfnd_sod_rules
    for each row
declare
    l_tmp varchar2(30);
begin
    if :new.role_code_1 > :new.role_code_2 then
        l_tmp := :new.role_code_1;
        :new.role_code_1 := :new.role_code_2;
        :new.role_code_2 := l_tmp;
    end if;
end;
/

-- An employee's user name changed (Fusion user name from the HCM sync, or a LOCAL edit): every stored reference
-- moves to the new name (xxfnd_security_pkg.rename_user), so the person keeps their requests, cases and tasks.
create or replace trigger xxfnd_employees_rename
    after update of user_name on xxfnd_employees
    for each row
    when (upper(new.user_name) <> upper(old.user_name))
begin
    xxfnd_security_pkg.rename_user(:old.user_name, :new.user_name);
end;
/
